// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    function setUp() public { c = new StaxLPStaking(address(this), address(this)); }
    function testRegression_property() public {
        address newMigrator = address(0x123);
        c.setMigrator(newMigrator);
        address dummyToken = address(0x456);
        c.addReward(dummyToken);
        assertTrue(c.migrator() == newMigrator);
    }
}
